SELECT w.web_name, hd.hd_dep_count, sm.sm_type, SUM(ws.ws_net_paid_inc_tax) AS total_paid, AVG(ws.ws_ext_tax) AS avg_tax, PERCENT_RANK() OVER (PARTITION BY w.web_name ORDER BY SUM(ws.ws_net_paid_inc_tax)) AS revenue_percentile FROM web_sales ws JOIN web_site w ON ws.ws_web_site_sk = w.web_site_sk JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE ws.ws_quantity > 20 AND ws.ws_coupon_amt = 0 GROUP BY w.web_name, hd.hd_dep_count, sm.sm_type HAVING AVG(ws.ws_ext_tax) BETWEEN 1 AND 5 ORDER BY revenue_percentile DESC, total_paid
